# Roteiro do Brasileiro Padrão #01 "Ele recebeu um Pix de R$ 50 milhões por engano". Gera public/bp/v01/roteiro.json.
# Cada fala: q (quem fala: n narrador, v Valdir, d Dona Neide, g golpista, e gerente, l delegado), txt, e opcionais:
# s = plano novo (tipo + parâmetros; sem s a fala continua no plano anterior), hud = saldo no extrato (None esconde),
# m = troca a trilha a partir dali, p = pausa extra, ex/cfg = emoção da voz.
import json
F = []
def f(q, txt, s=None, **k): F.append({'q': q, 'txt': txt, **({'s': s} if s else {}), **k})
S = lambda t, **k: {'t': t, **k}
# ---------- abertura ----------
f('n', 'Três e doze da manhã. Um porteiro de Guarulhos recebe um Pix de cinquenta milhões de reais. Por engano.', S('cel', tela='pix', valor=50000000, de='BOI GORDO AGRO S.A.', hora='03:12', pal='cinquenta'), m='tensao', hud=None, ex=0.6)
f('v', 'Eita, rapaz... cinquenta milhão?', S('close', quem='valdir', expr='susto', fundo='dentroNoite', pose='celular', zoom='susto'), ex=0.85, cfg=0.3, hud=50000037.12)
f('n', 'Um minuto antes, o saldo dele era de trinta e sete reais e doze centavos.', S('cel', tela='saldo', pal='trinta'), hud=37.12)
f('n', 'Nas próximas setenta e duas horas, três pessoas vão atrás desse dinheiro: um golpista, uma gerente de banco e um delegado.', S('visita', quem=['golpista', 'gerente', 'delegado'], pal=['um golpista', 'uma gerente', 'um delegado'], relogio=72), hud=50000037.12)
f('n', 'E o Valdir só precisa apertar um botão. O problema é que a maioria das pessoas aperta o errado.', S('cel', tela='botoes', placa='A MAIORIA APERTA O ERRADO', pal='errado'))
f('n', 'Fica até o fim, porque um dos botões leva o Valdir pra delegacia. E o outro muda a vida dele.', p=0.2)
f('n', 'Tudo começou seis horas antes.', S('relogio', de=3.2, ate=21.2, txt='6 HORAS ANTES'), m='', hud=None, p=0.2)
# ---------- ato 1 ----------
f('n', 'Vinte e uma e doze. O Valdir assume a portaria do Edifício Jatobá.', S('chegada'), m='cotidiano', hud=None)
f('d', 'Boa noite, Valdir! Chegou a minha encomenda?', S('ots', frente='neide', costas='valdir', fundo='rua'), ex=0.6, hud=37.12)
f('v', 'Chegou hoje à tarde, Dona Neide. Tá aqui.', S('ots', frente='valdir', costas='neide', fundo='guarita', pose='entrega', expr='sorriso'))
f('n', 'Dezenove anos de portaria. Nenhuma encomenda perdida.', S('mesa', modo='caderno', carimbo='dezenove', check='nenhuma', placa='ENCOMENDAS PERDIDAS: 0'))
f('d', 'Você devia ganhar mais, viu?', S('close', quem='neide', expr='bronca', fundo='rua', torto=1), ex=0.6)
f('v', 'Deixa comigo.', S('close', quem='valdir', expr='confiante', fundo='dentro', pose='joia', bal='Deixa comigo.'), ex=0.6, p=0.3)
f('n', 'Era o que ele sempre dizia. Pro síndico, pro entregador, pro boleto atrasado.', S('mesa', modo='boletos', pal=['síndico', 'entregador', 'boleto']))
f('n', 'O salário: mil oitocentos e trinta reais. O aluguel: novecentos. O que sobrava no fim do mês cabia numa mão.', S('cel', tela='saldo', pal='sobrava'))
f('n', 'Se você já gostou do Valdir, se inscreve no canal. Ele agradece.', S('close', quem='valdir', expr='sorriso', fundo='dentro', pose='joia', placa='INSCREVA-SE', pal='inscreve'), p=0.3)
# ---------- o Pix ----------
f('n', 'Às três e doze, o celular vibrou.', S('relogio', de=21.2, ate=3.2, txt='6 HORAS DEPOIS'), m='')
f('n', 'O remetente era uma empresa de gado do Mato Grosso. Alguém digitou a chave errada. Um número de diferença.', S('mesa', modo='vibra'), m='tensao', p=0.1)
f('n', 'Só um número.', S('cel', tela='chave', pal='número'), hud=50000037.12)
f('n', 'Durante dez minutos, o Valdir só olhou pra tela. Conferiu o nome. Conferiu os zeros. Sete zeros.', S('cel', tela='pix', valor=50000000, de='BOI GORDO AGRO S.A.', hora='03:22', pal='durante', parado=1))
f('v', 'Deve ser vírus.', S('close', quem='valdir', expr='neutro', fundo='dentroNoite', pose='celular'), p=0.2)
f('v', 'Cinquenta milhões... Isso dá quantos anos de salário?', S('close', quem='valdir', expr='susto', fundo='dentroNoite', pose='celular'), ex=0.7)
f('n', 'Mais de dois mil e duzentos anos.', S('texto', txt='2.276 ANOS', sub='de salário de porteiro', cor='verde'), p=0.2)
f('n', 'E foi aí que a cabeça do Valdir começou a gastar.', S('close', quem='valdir', expr='sorriso', fundo='dentroNoite', olhar=[0.2, -0.8], zoom='entra'), m='')
# ---------- o Valdir que gasta ----------
f('n', 'Primeiro, um carro zero.', S('sonho', item='carro'), m='sonho', hud=49800037.12)
f('n', 'Depois, churrasco pro prédio inteiro, todo domingo.', S('sonho', item='churrasco'), hud=49500037.12)
f('v', 'Pode pegar mais picanha, Dona Neide!', ex=0.75)
f('n', 'Uma casa na praia.', S('sonho', item='praia'), hud=47500037.12)
f('n', 'E um barco que ele nem sabe pilotar.', S('sonho', item='barco'), hud=46000037.12)
f('n', 'E um áudio pro síndico, pedindo as contas.', S('sonho', item='audio'))
f('v', 'Deixa comigo, não. Agora deixa com outro!', ex=0.8)
f('n', 'Em um mês, o Valdir da imaginação já tinha torrado quatro milhões.', S('extrato', titulo='O VALDIR DA IMAGINAÇÃO', linhas=[['Carro zero', -200000], ['Churrasco todo domingo', -300000], ['Casa na praia', -2000000], ['Barco', -1500000]], total='- R$ 4.000.000,00'))
f('n', 'Só que esse Valdir esqueceu de um detalhe.', S('close', quem='valdir', expr='neutro', fundo='dentroNoite', zoom='entra'), m='', hud=50000037.12, p=0.2)
# ---------- lição 1 ----------
f('n', 'Lição número um: dinheiro que cai na sua conta por engano não é seu.', S('cartao', n=1, titulo='Caiu por engano? Não é seu.', linhas=['Ficar com o dinheiro é crime', 'Código Penal, artigo 169', 'Detenção de 1 mês a 1 ano, ou multa', 'E ainda tem que devolver tudo, corrigido']), m='reflexao')
f('n', 'Ficar com ele é crime.')
f('n', 'Tá no artigo cento e sessenta e nove do Código Penal: detenção de um mês a um ano, ou multa.')
f('n', 'E a Justiça ainda manda devolver tudo, com correção.')
f('n', 'Ou seja: o Valdir da imaginação ia terminar sem o barco, sem a casa e com um processo.', S('sonho', item='barco', afunda=1), m='')
f('v', 'Melhor devolver.', S('close', quem='valdir', expr='neutro', fundo='dentroNoite', pose='celular'), p=0.2)
f('n', 'Só que devolver também tem armadilha.', S('cel', tela='botoes'), m='tensao', p=0.3)
# ---------- o golpista ----------
f('n', 'Sete da manhã. O telefone toca.', S('cel', tela='ligacao', hora='07:00'), m='')
f('g', 'Seu Valdir? Aqui é do financeiro da Boi Gordo. O senhor recebeu um Pix nosso por engano.', S('duplo', fala='g'), m='tensao', ex=0.6)
f('v', 'Recebi, sim. Já ia devolver.', S('duplo', fala='v'))
f('g', 'Ótimo! Só que aquela conta foi bloqueada. Faz um Pix novo pra esta outra chave, que eu vou te passar.', S('duplo', fala='g', chave=1), ex=0.65)
f('n', 'Parece ajuda. É golpe.', S('texto', txt='É GOLPE', sub='parece ajuda', cor='verm'), p=0.2)
f('n', 'Esse golpe tem nome: golpe do Pix errado. E ele funciona porque a vítima acha que está sendo honesta.', S('cel', tela='chave2'))
f('n', 'Esse homem não trabalha na empresa. Ele só quer que o Valdir mande o dinheiro pra conta dele.', S('close', quem='golpista', expr='sorriso', fundo='covil', zoom='entra'))
f('n', 'E se o Valdir mandasse, ia continuar devendo os cinquenta milhões pra dona de verdade.', S('extrato', titulo='SE ELE CAI NO GOLPE', linhas=[['Pix novo para o golpista', -50000000], ['Dívida com a dona do dinheiro', -50000000]], total='- R$ 100.000.000,00'))
f('n', 'Lição número dois: nunca devolva fazendo um Pix novo.', S('cartao', n=2, titulo='Nunca devolva com um Pix novo.', linhas=['Use o botão DEVOLVER', 'Ele fica dentro da própria transação', 'O dinheiro volta para a conta de onde veio']), m='reflexao')
f('n', 'Use o botão devolver, que fica dentro da própria transação.')
f('n', 'Ele manda o dinheiro de volta pra conta de onde veio.')
f('v', 'O senhor me dá licença, que eu vou apertar o botão certo.', S('duplo', fala='v', expr='confiante'), m='')
f('g', 'Não, não, espera!', S('duplo', fala='g', expr='susto', desliga=1), ex=0.9, cfg=0.3, p=0.4)
# ---------- a gerente ----------
f('n', 'Meio-dia. Uma gerente de banco aparece na portaria. De terninho. Num prédio que nunca recebeu gerente nenhum.', S('visita', quem=['gerente'], dia=1, hora='12:00'), m='cotidiano')
f('e', 'Seu Valdir, eu vim pessoalmente. A empresa pediu o dinheiro de volta pelo sistema do Banco Central, e não funcionou.', S('ots', frente='gerente', costas='valdir', fundo='ruaDia'), ex=0.55)
f('n', 'Ela tá falando do MED, o Mecanismo Especial de Devolução.', S('cartao', n=3, titulo='O MED não cobre erro de digitação.', linhas=['MED: Mecanismo Especial de Devolução', 'Vale para golpe, fraude e falha do sistema', 'Não vale para erro de quem enviou', 'Nesse caso, a devolução não é automática']), m='reflexao')
f('n', 'Lição número três: o MED serve pra golpe, fraude e falha do sistema.')
f('n', 'Pra erro de digitação de quem enviou, ele não vale.')
f('n', 'Nesse caso, a devolução não é automática. Ela depende do Valdir.')
f('e', 'Se o senhor quisesse, podia dificultar muito a nossa vida.', S('close', quem='gerente', expr='bronca', fundo='ruaDia'), m='')
f('v', 'A senhora aceita um café?', S('ots', frente='valdir', costas='gerente', fundo='guaritaDia', expr='sorriso'))
f('e', 'Eu aceito a devolução.', S('close', quem='gerente', expr='neutro', fundo='ruaDia'), p=0.2)
f('v', 'Dona, eu nunca perdi nem encomenda de sabonete. Não vou perder cinquenta milhões dos outros.', S('ots', frente='valdir', costas='gerente', fundo='guaritaDia', expr='confiante'))
f('n', 'Se você faria igual ao Valdir, deixa o like. Se ia pensar duas vezes, pode confessar nos comentários.', S('close', quem='valdir', expr='sorriso', fundo='dentro', pose='joia', placa='E VOCÊ?', pal='confessar'), m='cotidiano', p=0.3)
# ---------- a virada ----------
f('n', 'O Valdir abriu o aplicativo e apertou devolver.', S('cel', tela='botoes', aperta='devolver', pal='apertou'), m='')
f('n', 'E nada aconteceu.', p=0.3)
f('n', 'O celular dele, de dois mil e dezesseis, travou. Bateria em um por cento.', S('cel', tela='travado'), m='tensao')
f('v', 'Agora não, pelo amor de Deus!', S('close', quem='valdir', expr='susto', fundo='dentro', pose='celular', zoom='susto'), ex=0.85, cfg=0.3)
f('n', 'Dezoito horas. Um carro da polícia para na frente do prédio.', S('aereo', quem='policia', hora='18:00'))
f('l', 'Valdir Aparecido de Souza? A empresa registrou ocorrência. O senhor precisa me acompanhar.', S('ots', frente='delegado', costas='valdir', fundo='rua'), ex=0.5)
f('n', 'Pra quem olha de fora, quinze horas com cinquenta milhões na conta parece outra coisa.', S('close', quem='valdir', expr='susto', fundo='rua', luzes=1, zoom='entra'))
f('n', 'Na delegacia, o Valdir fez a única coisa que sabia fazer.', S('ots', frente='valdir', costas='delegado', fundo='delegacia', expr='neutro'), m='')
f('v', 'Doutor, o senhor me empresta um carregador?', ex=0.6)
f('n', 'Ele ligou o celular na tomada da delegacia, abriu o aplicativo na frente de todo mundo e apertou devolver.', S('cel', tela='botoes', aperta='devolver', pal='apertou', cabo=1), m='reflexao')
f('n', 'O escrivão parou de digitar. O delegado tirou os óculos. Até o preso da cela ao lado esticou o pescoço.', S('close', quem='delegado', expr='susto', fundo='delegacia', zoom='entra'))
f('n', 'Cinquenta milhões de reais saíram da conta. O saldo voltou pra trinta e sete e doze.', S('cel', tela='devolvido', pal='saíram'), hud=37.12)
f('l', 'Em vinte anos de polícia, eu nunca vi ninguém devolver tão rápido.', S('close', quem='delegado', expr='sorriso', fundo='delegacia'), ex=0.55)
f('v', 'É que eu tô sem bateria, doutor.', S('close', quem='valdir', expr='sorriso', fundo='delegacia', pose='celular'), p=0.4)
# ---------- final ----------
f('n', 'O Valdir voltou pro turno da noite. Mesmo uniforme. Mesma guarita. Mesmo saldo.', S('chegada'), m='cotidiano')
f('d', 'E aí, ficou rico?', S('ots', frente='neide', costas='valdir', fundo='rua'), ex=0.6)
f('v', 'Fiquei não, Dona Neide. Mas tô com a consciência limpa.', S('ots', frente='valdir', costas='neide', fundo='guarita', expr='sorriso'), p=0.3)
f('d', 'Cinquenta milhões, Valdir! Eu teria pelo menos comprado um pão de queijo antes.', S('close', quem='neide', expr='bronca', fundo='rua', torto=1), ex=0.7)
f('n', 'Três dias depois, às três e doze da manhã, o celular vibrou de novo.', S('mesa', modo='vibra'), m='')
f('n', 'Era a Boi Gordo. E dessa vez não foi engano.', S('cel', tela='pix', valor=50000, de='BOI GORDO AGRO S.A.', hora='03:12', pal='dessa', recado='Obrigado pela honestidade.'), m='reflexao', hud=50037.12)
f('v', 'Eita.', S('close', quem='valdir', expr='susto', fundo='dentroNoite', pose='celular', zoom='susto'), ex=0.8, cfg=0.3)
f('n', 'Cinquenta mil reais. Com um recado: obrigado pela honestidade.', S('texto', txt='R$ 50.000,00', sub='"Obrigado pela honestidade."', cor='verde'))
f('n', 'Não era o barco. Mas dava pra trocar o celular.', S('close', quem='valdir', expr='sorriso', fundo='dentro', pose='celular', novo=1), m='cotidiano', p=0.3)
f('n', 'E você? Se caíssem cinquenta milhões na sua conta por engano, o que você faria nas primeiras setenta e duas horas? Conta aqui embaixo.', S('fim', modo='pergunta'), hud=None)
f('n', 'E se inscreve no canal, porque semana que vem o Valdir encontra uma mala esquecida no elevador.', S('fim', modo='proximo'))
f('v', 'Deixa comigo.', S('close', quem='valdir', expr='confiante', fundo='dentro', pose='joia', bal='Deixa comigo.'), ex=0.6, p=1.2)
for i, x in enumerate(F): x['c'] = f'f{i:02d}'
json.dump({'falas': F}, open('public/bp/v01/roteiro.json', 'w'), ensure_ascii=False, indent=1)
print(len(F), 'falas,', sum(len(x['txt'].split()) for x in F), 'palavras,', sum(1 for x in F if 's' in x), 'planos')
